// Edited annual WACC path uses the same exact calendar dates, without inventing
// an extra period. Constant paths retain the direct power used by source Python.
export function discountNflxPath(core,rates,terminalRate){
 require(Array.isArray(rates)&&rates.length===10,'Ten WACCs required');rates.forEach(v=>num(v,'Annual WACC',.001,.5));num(terminalRate,'Terminal WACC',.001,.5);require(terminalRate>core.resolved_assumptions.terminal_growth,'Terminal WACC must exceed growth');
 const out=clone(core);let factor=1,previous=0;const constant=rates.every(v=>v===rates[0]);out.discount_factors={};out.forecast.forEach((r,i)=>{factor=constant?(1+rates[0])**r.discount_time_years:factor*(1+rates[i])**(r.discount_time_years-previous);previous=r.discount_time_years;r.pv_fcff=r.fcff/factor;out.discount_factors[r.year]=factor;});out.terminal.undiscounted_terminal_value=out.terminal.fcff/(terminalRate-out.resolved_assumptions.terminal_growth);out.terminal.terminal_pv=out.terminal.undiscounted_terminal_value/factor;out.explicit_pv=sum(out.forecast.map(r=>r.pv_fcff));out.terminal_pv=out.terminal.terminal_pv;out.operating_ev=out.explicit_pv+out.terminal_pv;out.terminal_ev_fraction=out.operating_ev?out.terminal_pv/out.operating_ev:null;out.annual_wacc_path=clone(rates);out.terminal_wacc=terminalRate;return finiteTree(out);
}

function validateNflxCoreForAllocation(core){
 require(object(core)&&['bear','base','bull'].includes(core.case),'Valid operating case required');
 const data={common:clone(core.resolved_common),cases:Object.fromEntries(['bear','base','bull'].map(name=>[name,clone(core.resolved_assumptions)]))};
 let expected=evaluateNflx(data,core.case);
 if(Object.hasOwn(core,'annual_wacc_path'))expected=discountNflxPath(expected,core.annual_wacc_path,core.terminal_wacc);
 else require(!Object.hasOwn(core,'discount_factors')&&!Object.hasOwn(core,'terminal_wacc'),'Unmatched discount path');
 const compare=(a,b)=>{if(typeof b==='number')return finite(a)&&Math.abs(a-b)<=Math.max(1e-8,Math.abs(b)*1e-12);if(Array.isArray(b))return Array.isArray(a)&&a.length===b.length&&b.every((v,i)=>compare(a[i],v));if(object(b))return object(a)&&Object.entries(b).every(([k,v])=>compare(a[k],v));return a===b;};
 require(compare(core,expected),'Operating output does not reconcile to its validated assumptions');
}
